INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11901, 'នៅក្នុងស្ថិតិ តើពាក្យ «ប្រជាករ» (Population) មានន័យដូចម្តេច?', NULL, '["សំណុំនៃធាតុទាំងអស់ដែលត្រូវធ្វើការសិក្សាឬអង្កេត", "សំណុំរងដែលដកស្រង់ចេញពីការអង្កេត", "ផលដកតម្លៃធំបំផុតនិងតូចបំផុត", "ចំនួនមធ្យមនៃទិន្នន័យទាំងអស់"]', 0, NULL, 1, 'mcq', 'ប្រជាករ គឺជាសំណុំទាំងមូលនៃបុគ្គល ឬវត្ថុ ឬព្រឹត្តិការណ៍ទាំងអស់ដែលអ្នកស្រាវជ្រាវចាប់អារម្មណ៍សិក្សា។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'easy', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11902, 'តើផលបូកនៃប្រេកង់ទាំងអស់ \(\sum f_i\) ស្មើនឹងអ្វី?', NULL, '["តម្លៃមធ្យមនៃទិន្នន័យ", "ផលបូកតម្លៃទិន្នន័យ", "ទំហំគំរូសរុប n (ចំនួនទិន្នន័យទាំងអស់)", "ចំនួនថ្នាក់ស្ថិតិ"]', 2, NULL, 1, 'mcq', 'ផលបូកប្រេកង់ទាំងអស់គឺជាចំនួនអង្កេតសរុប គឺទំហំគំរូ n = \sum f_i។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'easy', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11903, 'ចន្លោះថ្នាក់មួយត្រូវបានកំណត់ដោយ \([50,\, 60)\)។ រកចំណុចកណ្តាលថ្នាក់ (Class Mark) នៃចន្លោះថ្នាក់នេះ៖', NULL, '["10", "60", "50", "55"]', 3, NULL, 1, 'mcq', 'ចំណុចកណ្តាលថ្នាក់ x_i = (50 + 60) / 2 = 110 / 2 = 55។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'easy', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11904, 'នៅលើក្រាបផ្លិត (Pie Chart) តើមុំសរុបនៅផ្ចិតនៃរង្វង់ស្មើនឹងប៉ុន្មានដឺក្រេ?', NULL, '["\\(180^\\circ\\)", "\\(360^\\circ\\)", "\\(90^\\circ\\)", "\\(100^\\circ\\)"]', 1, NULL, 1, 'mcq', 'មុំនៅផ្ចិតនៃរង្វង់ទាំងមូលមានតម្លៃ 360 ដឺក្រេ។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'easy', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11905, 'តើអ្វីជា «គំរូ» (Sample) ក្នុងការស្រាវជ្រាវស្ថិតិ?', NULL, '["សំណុំរងនៃប្រជាករដែលត្រូវបានជ្រើសរើសមកសិក្សាជាក់ស្តែង", "សំណុំនៃប្រជាករទាំងមូលគ្មានសល់", "តម្លៃធំបំផុតនៃទិន្នន័យដែលប្រមូលបាន", "រូបមន្តសម្រាប់គណនាមធ្យមភាគ"]', 0, NULL, 1, 'mcq', 'គំរូ គឺជាផ្នែកមួយ ឬសំណុំរងមួយនៃប្រជាករដែលគេជ្រើសរើសយកមកប្រមូលទិន្នន័យដើម្បីធ្វើការសន្និដ្ឋានលើប្រជាករទាំងមូល។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'easy', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11906, 'តើរូបមន្តគណនាប្រេកង់ធៀប \(f_r\) នៃតម្លៃទិន្នន័យមួយដែលមានប្រេកង់ \(f_i\) ក្នុងចំណោមទិន្នន័យសរុប \(n\) គឺជាអ្វី?', NULL, '["\\(f_r = \\dfrac{n}{f_i}\\)", "\\(f_r = f_i \\times n\\)", "\\(f_r = \\dfrac{f_i}{n}\\)", "\\(f_r = \\dfrac{f_i}{\\sum x_i}\\)"]', 2, NULL, 1, 'mcq', 'ប្រេកង់ធៀប គឺជាផលធៀបរវាងប្រេកង់នៃតម្លៃនោះ និងទំហំគំរូសរុប f_r = f_i / n។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'easy', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11907, 'ចន្លោះថ្នាក់មួយគឺ \([20,\, 35)\)។ រកទំហំថ្នាក់ (Class Width) \(c\) នៃចន្លោះនេះ៖', NULL, '["27.5", "15", "35", "20"]', 1, NULL, 1, 'mcq', 'ទំហំថ្នាក់ c = ព្រំដែនលើ - ព្រំដែនក្រោម = 35 - 20 = 15។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'easy', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11908, 'ទិន្នន័យមួយមានប្រេកង់ធៀបស្មើនឹង \(20\%\) (ឬ 0.20)។ គណនាមុំផ្ចិតតំណាងទិន្នន័យនេះនៅលើក្រាបផ្លិត៖', NULL, '["\\(72^\\circ\\)", "\\(36^\\circ\\)", "\\(20^\\circ\\)", "\\(54^\\circ\\)"]', 0, NULL, 1, 'mcq', 'មុំផ្ចិត \theta = 0.20 \times 360^\circ = 72^\circ។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'easy', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11909, 'តើទិន្នន័យមួយណាជា «អថេរគុណភាព» (Qualitative Variable)?', NULL, '["ពិន្ទុប្រឡងគណិតវិទ្យា", "កម្ពស់សិស្ស (គិតជា cm)", "ទម្ងន់ផ្លែឈើ (គិតជា kg)", "ប្រភេទឈាម (A, B, AB, O)"]', 3, NULL, 1, 'mcq', 'អថេរគុណភាព ពិពណ៌នាអំពីលក្ខណៈ ឬប្រភេទដែលមិនមែនជាតម្លៃលេខរង្វាស់ ដូចជាប្រភេទឈាម ភេទ ពណ៌សម្បុរ។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'easy', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11910, 'ក្នុងគំរូទិន្នន័យដែលមានចំនួនសរុប \(n = 40\) មានប្រេកង់នៃថ្នាក់មួយស្មើ \(f_i = 10\)។ គណនាប្រេកង់ធៀបជាភាគរយនៃថ្នាក់នោះ៖', NULL, '["20%", "40%", "25%", "10%"]', 2, NULL, 1, 'mcq', 'f_r\% = (10 / 40) * 100% = 0.25 * 100% = 25%។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'easy', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11911, 'តើការវាស់វែងមួយណាជា «អថេរបរិមាណជាប់» (Continuous Quantitative Variable)?', NULL, '["រយៈពេលធ្វើដំណើរពីផ្ទះទៅសាលារៀន (គិតជានាទី)", "ពិន្ទុដែលទទួលបានពីការឆ្លើយសំណួរ 10", "ចំនួនគ្រាប់ឡុកឡាក់ដែលបោះបាន", "ចំនួនសៀវភៅក្នុងកាតាប"]', 0, NULL, 2, 'mcq', 'អថេរជាប់ អាចទទួលតម្លៃណាមួយក្នុងចន្លោះជាក់លាក់មួយ រួមទាំងចំនួនទសភាគ ដូចជាពេលវេលា ប្រវែង ទម្ងន់។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'medium', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11912, 'គេមានតារាងប្រេកង់ដែលមាន \(n = 50\)។ ប្រសិនបើប្រេកង់នៃថ្នាក់បួនដំបូងគឺ 8, 14, 16, 7 នោះប្រេកង់នៃថ្នាក់ទីប្រាំចុងក្រោយគឺ៖', NULL, '["8", "5", "4", "6"]', 1, NULL, 2, 'mcq', 'f_5 = 50 - (8 + 14 + 16 + 7) = 50 - 45 = 5។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'medium', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11913, 'ទិន្នន័យមានតម្លៃតូចបំផុត \(x_{\min} = 24\) និងតម្លៃធំបំផុត \(x_{\max} = 84\)។ បើគេចង់បែងចែកជា 6 ថ្នាក់ស្មើៗគ្នា តើទំហំថ្នាក់ \(c\) គួរស្មើនឹងប៉ុន្មាន?', NULL, '["8", "10", "14", "12"]', 1, NULL, 2, 'mcq', 'ផលសង r = 84 - 24 = 60។ ទំហំថ្នាក់ c = r / k = 60 / 6 = 10។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'medium', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
