INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11914, 'ពិនិត្យអ៊ីស្តូក្រាមក្នុងរូបខាងក្រោម។ តើចន្លោះថ្នាក់ណាដែលមានប្រេកង់ខ្ពស់ជាងគេបង្អស់ (ថ្នាក់ម៉ូត)?', 'g10-2dda80c435.svg', '["\\([70,\\, 80)\\)", "\\([60,\\, 70)\\)", "\\([50,\\, 60)\\)", "\\([40,\\, 50)\\)"]', 1, NULL, 2, 'mcq', 'នៅលើអ៊ីស្តូក្រាម សសរខ្ពស់បំផុតគឺចន្លោះ [60, 70) ដែលមានកម្ពស់ប្រេកង់ស្មើ 15។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'medium', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11915, 'គេមានទិន្នន័យ 12, 15, 12, 18, 15, 12, 20, 18, 12, 15។ គណនាប្រេកង់ធៀបនៃតម្លៃ 12៖', NULL, '["0.25 (ឬ 25%)", "0.30 (ឬ 30%)", "0.40 (ឬ 40%)", "0.50 (ឬ 50%)"]', 2, NULL, 2, 'mcq', 'ចំនួនទិន្នន័យសរុប n = 10។ តម្លៃ 12 កើតឡើងចំនួន 4 ដង នាំឱ្យ f_r = 4 / 10 = 0.40 (40%)។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'medium', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11916, 'គេមានចន្លោះថ្នាក់ \([40,\, 50)\), \([50,\, 60)\), \([60,\, 70)\) ដែលមានប្រេកង់រៀងគ្នា 6, 10, 4។ គណនាផលបូក \(\sum f_i x_i\)៖', NULL, '["1150", "1050", "1100", "980"]', 2, NULL, 2, 'mcq', 'ចំណុចកណ្តាលថ្នាក់ x_i គឺ 45, 55, 65។ ផលបូក = 6(45) + 10(55) + 4(65) = 270 + 550 + 260 = 1080? ពិនិត្យ: 270 + 550 = 820 + 260 = 1080។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'medium', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11917, 'យោងតាមអ៊ីស្តូក្រាមដដែល គណនាចំនួនទិន្នន័យសរុប \(n\) ដែលបានបង្ហាញ៖', 'g10-2dda80c435.svg', '["35", "50", "45", "40"]', 3, NULL, 2, 'mcq', 'n = 4 + 10 + 15 + 8 + 3 = 40។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'medium', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11918, 'គេមានប្រេកង់បន្តបន្ទាប់នៃ 4 ថ្នាក់គឺ 5, 9, 12, 6។ គណនា «ប្រេកង់កើន» (Cumulative Frequency) នៃថ្នាក់ទី 3៖', NULL, '["26", "32", "12", "14"]', 0, NULL, 2, 'mcq', 'ប្រេកង់កើននៃថ្នាក់ទី 3 គឺ F_3 = f_1 + f_2 + f_3 = 5 + 9 + 12 = 26។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'medium', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11919, 'ក្នុងតារាងបំណែងចែកប្រេកង់ ថ្នាក់មួយមានចំណុចកណ្តាល \(x_i = 35\) និងទំហំថ្នាក់ \(c = 10\)។ កំណត់ចន្លោះថ្នាក់នោះ៖', NULL, '["\\([20,\\, 50)\\)", "\\([30,\\, 40)\\)", "\\([35,\\, 45)\\)", "\\([25,\\, 45)\\)"]', 1, NULL, 2, 'mcq', 'ព្រំដែនក្រោម = 35 - 10/2 = 30 និងព្រំដែនលើ = 35 + 10/2 = 40 នាំឱ្យចន្លោះគឺ [30, 40)។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'medium', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11920, 'ផ្អែកលើអ៊ីស្តូក្រាមដដែល គណនាភាគរយនៃទិន្នន័យដែលមានតម្លៃចាប់ពី 70 ឡើងទៅ (ចន្លោះ [70, 90))៖', 'g10-2dda80c435.svg', '["25%", "30%", "20%", "27.5%"]', 3, NULL, 2, 'mcq', 'ប្រេកង់ចន្លោះចាប់ពី 70 ឡើងទៅគឺ 8 + 3 = 11។ ភាគរយ = (11 / 40) * 100% = 27.5%។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'medium', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11921, 'ក្នុងគំរូមួយដែលមាន \(n = 80\) គេដឹងថាប្រេកង់ធៀបនៃថ្នាក់ A គឺ \(0.35\)។ តើថ្នាក់ A មានប្រេកង់ស្មើនឹងប៉ុន្មាន?', NULL, '["28", "30", "35", "24"]', 0, NULL, 2, 'mcq', 'f_A = f_r * n = 0.35 * 80 = 28។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'medium', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11922, 'តារាងមួយមានចន្លោះថ្នាក់ [10, 20), [20, 30), [30, 40), [40, 50) ដែលមានប្រេកង់ 4, 8, 12, 6។ គណនាប្រេកង់កើនធៀបជាភាគរយ \(F_r\%\) នៃថ្នាក់ទី 2៖', NULL, '["50%", "26.7%", "40%", "30%"]', 2, NULL, 2, 'mcq', 'n = 4 + 8 + 12 + 6 = 30។ ប្រេកង់កើននៃថ្នាក់ទី 2 គឺ F_2 = 4 + 8 = 12។ ភាគរយកើន = (12 / 30) * 100% = 40%។', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'medium', 1, '10', 'បំណែងចែកប្រេកង់និងតារាងក្រាប', 'ជំពូកទី 7 : ស្ថិតិ', NULL, 0);
